INSERT INTO public.junior_grammar_questions (id, point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type, grammar_topic, distractors) SELECT gen_random_uuid(), (SELECT id FROM public.junior_grammar_points WHERE code='g9u1.01'), '— How do you improve your English? — I improve it ____ English songs.', 'by sing', 'by singing', 'to sing', 'singing', 'B', 'by 后接动名词。', 1, 1, 'mcq', 'g9u1.01', '[]'::jsonb WHERE NOT EXISTS (SELECT 1 FROM public.junior_grammar_questions x JOIN public.junior_grammar_points p ON x.point_id=p.id WHERE p.code='g9u1.01' AND x.stem='— How do you improve your English? — I improve it ____ English songs.');
