INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) SELECT gen_random_uuid(), 9, 'Becoming a Good Learner', 'Good learners are not born; they are made. They believe that everyone can learn well by finding the right way. First, good learners are active. They do not just wait for the teacher to tell them everything. Instead, they ask questions and try to find the answers by themselves. Second, good learners are patient. They know that making mistakes is a normal part of learning, so they never give up. Third, good learners connect new knowledge with what they already know. For example, when they meet a new word, they make a sentence with it so that they can remember it better. Finally, good learners study wisely. They plan their time and review what they have learned often. If you follow these tips, you can become a good learner, too.', '说明文', 130, '[{"q": "What is the passage mainly about?", "answer": "A", "options": ["How to become a good learner.", "The history of English.", "How to make friends.", "Why exams are hard."], "explanation": "全文讲怎样成为优秀学习者。"}, {"q": "Good learners are active because they ____.", "answer": "B", "options": ["wait for the teacher", "ask questions and find answers themselves", "never study at home", "only read textbooks"], "explanation": "原文:they ask questions and try to find the answers by themselves。"}, {"q": "What do good learners think about mistakes?", "answer": "C", "options": ["They are terrible.", "They should be hidden.", "They are a normal part of learning.", "They mean failure."], "explanation": "原文:making mistakes is a normal part of learning。"}, {"q": "How do good learners remember a new word?", "answer": "D", "options": ["By reading it once.", "By writing it many times.", "By ignoring it.", "By making a sentence with it."], "explanation": "原文:make a sentence with it so that they can remember it better。"}, {"q": "The word “wisely” here means ____.", "answer": "B", "options": ["in a lazy way", "in a smart and sensible way", "in a hurry", "by luck"], "explanation": "wisely=明智地。"}]'::jsonb, '[]'::jsonb, 3, 'g9', 'U1' WHERE NOT EXISTS (SELECT 1 FROM public.junior_reading WHERE volume='g9' AND unit='U1' AND title='Becoming a Good Learner');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) SELECT gen_random_uuid(), 9, 'Anna and Her Reading Journey', 'When Anna was young, she hated reading. The books at school looked boring, and she could not understand many words. One summer, her aunt gave her a book about a girl who travelled around the world. Anna started reading just one page a day. Slowly, she wanted to know what would happen next, so she read more and more. Whenever she met a new word, she did not stop; she guessed its meaning from the story. By the end of the summer, she had finished five books. Reading had become her favourite hobby. Now Anna says that the secret is to start with something you really enjoy.', '记叙文', 107, '[{"q": "How did Anna feel about reading when she was young?", "answer": "C", "options": ["She loved it.", "She found it easy.", "She hated it.", "She never heard of it."], "explanation": "原文:she hated reading。"}, {"q": "Who gave Anna the book?", "answer": "D", "options": ["Her mother.", "Her teacher.", "Her friend.", "Her aunt."], "explanation": "原文:her aunt gave her a book。"}, {"q": "What did Anna do when she met a new word?", "answer": "A", "options": ["She guessed its meaning from the story.", "She looked it up at once.", "She skipped the whole book.", "She asked her aunt."], "explanation": "原文:she guessed its meaning from the story。"}, {"q": "How many books did Anna finish by the end of summer?", "answer": "B", "options": ["Three.", "Five.", "Two.", "Ten."], "explanation": "原文:she had finished five books。"}, {"q": "What is Anna''s secret to enjoying reading?", "answer": "C", "options": ["Read very fast.", "Use a dictionary often.", "Start with something you enjoy.", "Read one book a year."], "explanation": "原文:start with something you really enjoy。"}]'::jsonb, '[]'::jsonb, 2, 'g9', 'U1' WHERE NOT EXISTS (SELECT 1 FROM public.junior_reading WHERE volume='g9' AND unit='U1' AND title='Anna and Her Reading Journey');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) SELECT gen_random_uuid(), 9, 'Two Ways to Remember Words', 'Students often ask how to remember English words. There are two common ways. The first way is to write a word many times. This helps some students, but it can be boring, and you may forget the word soon. The second way is to use the word in real sentences. For example, if you learn the word “brave”, you can say, “My brother is brave.” This way takes more time at first, but you will remember the word much longer, because it is connected with a real idea. Many teachers believe the second way is better, because learning with meaning is stronger than learning by repeating alone.', '对比说明', 107, '[{"q": "What is the passage mainly about?", "answer": "D", "options": ["The history of English words.", "How to write quickly.", "Why words are difficult.", "Two ways to remember words."], "explanation": "主旨:记单词的两种方法。"}, {"q": "What is a problem with writing a word many times?", "answer": "A", "options": ["It can be boring and easily forgotten.", "It costs a lot of money.", "It needs a partner.", "It is not allowed."], "explanation": "原文:it can be boring, and you may forget the word soon。"}, {"q": "The example “My brother is brave” shows ____.", "answer": "B", "options": ["writing a word many times", "using a word in a real sentence", "reading a word aloud", "drawing a picture"], "explanation": "该例说明“在真实句子中使用单词”。"}, {"q": "Why is the second way better?", "answer": "C", "options": ["It is faster.", "It is easier.", "Learning with meaning is stronger.", "It needs no time."], "explanation": "原文:learning with meaning is stronger。"}, {"q": "Which way do many teachers prefer?", "answer": "D", "options": ["The first way.", "Neither way.", "Both equally.", "The second way."], "explanation": "原文:the second way is better。"}]'::jsonb, '[]'::jsonb, 3, 'g9', 'U1' WHERE NOT EXISTS (SELECT 1 FROM public.junior_reading WHERE volume='g9' AND unit='U1' AND title='Two Ways to Remember Words');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) SELECT gen_random_uuid(), 9, 'A Letter to a New Classmate', 'Dear Sam, Welcome to our class! I know learning English in a new school can be hard, so here are some tips. First, do not be afraid to make mistakes when you speak. Everyone makes them, and they help us learn. Second, try to read English for a few minutes every day, even just a comic book. Third, find a study partner so that you can practise together. Finally, be patient with yourself, because real progress takes time. If you ever need help, just ask me. I am sure you will do well. Your friend, Lily', '书信', 96, '[{"q": "Why did Lily write this letter?", "answer": "A", "options": ["To welcome Sam and give him study tips.", "To invite Sam to a party.", "To say goodbye to Sam.", "To borrow a book."], "explanation": "信的目的是欢迎并给学习建议。"}, {"q": "What does Lily say about mistakes?", "answer": "B", "options": ["They are useless.", "They help us learn.", "They should be hidden.", "They are dangerous."], "explanation": "原文:they help us learn。"}, {"q": "How often should Sam read English?", "answer": "C", "options": ["Once a week.", "Only at weekends.", "A few minutes every day.", "Three hours a day."], "explanation": "原文:read English for a few minutes every day。"}, {"q": "Why should Sam find a study partner?", "answer": "D", "options": ["To copy answers.", "To make money.", "To save time.", "To practise together."], "explanation": "原文:so that you can practise together。"}, {"q": "What is Lily''s last piece of advice?", "answer": "A", "options": ["Be patient with yourself.", "Buy many books.", "Study all night.", "Never ask for help."], "explanation": "原文:be patient with yourself。"}]'::jsonb, '[]'::jsonb, 2, 'g9', 'U1' WHERE NOT EXISTS (SELECT 1 FROM public.junior_reading WHERE volume='g9' AND unit='U1' AND title='A Letter to a New Classmate');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) SELECT gen_random_uuid(), 9, 'The Power of Mistakes', 'Many students are afraid of making mistakes. They keep quiet in class because they do not want to look silly. However, mistakes are not bad at all. In fact, they are an important part of learning. When you make a mistake and then correct it, your brain remembers the right answer better. Think about babies: they fall down many times before they learn to walk. Learning a language is the same. Every mistake shows you what to study next. So, the next time you make a mistake, do not feel sad. Be brave, learn from it, and try again. That is how good learners grow.', '议论文', 105, '[{"q": "Why do some students keep quiet in class?", "answer": "B", "options": ["They are tired.", "They are afraid of looking silly.", "They have no questions.", "They dislike English."], "explanation": "原文:they do not want to look silly。"}, {"q": "What happens when you correct a mistake?", "answer": "C", "options": ["Nothing happens.", "You feel sad.", "Your brain remembers the right answer better.", "You forget everything."], "explanation": "原文:your brain remembers the right answer better。"}, {"q": "Why does the writer mention babies?", "answer": "D", "options": ["To talk about families.", "To make readers laugh.", "To change the topic.", "To show that mistakes are part of learning."], "explanation": "以婴儿学步类比,说明犯错是学习的一部分。"}, {"q": "What does every mistake show you?", "answer": "A", "options": ["What to study next.", "Which friend to choose.", "When to sleep.", "Where to go."], "explanation": "原文:every mistake shows you what to study next。"}, {"q": "What does the writer advise readers to do?", "answer": "B", "options": ["Give up quickly.", "Be brave and learn from mistakes.", "Stay silent.", "Avoid all tests."], "explanation": "原文:Be brave, learn from it, and try again。"}]'::jsonb, '[]'::jsonb, 4, 'g9', 'U1' WHERE NOT EXISTS (SELECT 1 FROM public.junior_reading WHERE volume='g9' AND unit='U1' AND title='The Power of Mistakes');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) SELECT gen_random_uuid(), 9, 'Learning Beyond the Classroom', 'School is not the only place to learn English. There are many fun ways to practise outside the classroom. You can watch English cartoons or films with subtitles to train your ears. You can listen to English songs and sing along to improve your pronunciation. The Internet is also helpful: you can read short news stories or chat with online friends from other countries. Some students keep a diary in English to practise writing. The most important thing is to use English a little every day. When learning becomes part of your daily life, you will improve without even noticing it.', '应用说明', 101, '[{"q": "What is the passage mainly about?", "answer": "C", "options": ["The rules of grammar.", "A famous English teacher.", "Ways to practise English outside class.", "The history of films."], "explanation": "主旨:课外练英语的方法。"}, {"q": "How can watching films help you?", "answer": "D", "options": ["They cost nothing.", "They are short.", "They are funny.", "They train your ears."], "explanation": "原文:watch films with subtitles to train your ears。"}, {"q": "Why listen to English songs?", "answer": "A", "options": ["To improve pronunciation.", "To learn grammar rules.", "To make friends.", "To pass exams."], "explanation": "原文:sing along to improve your pronunciation。"}, {"q": "What do some students do to practise writing?", "answer": "B", "options": ["Watch more TV.", "Keep a diary in English.", "Play games.", "Sing songs."], "explanation": "原文:keep a diary in English to practise writing。"}, {"q": "What is the most important thing?", "answer": "C", "options": ["Study only before exams.", "Buy expensive books.", "Use English a little every day.", "Travel abroad."], "explanation": "原文:use English a little every day。"}]'::jsonb, '[]'::jsonb, 3, 'g9', 'U1' WHERE NOT EXISTS (SELECT 1 FROM public.junior_reading WHERE volume='g9' AND unit='U1' AND title='Learning Beyond the Classroom');
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) SELECT gen_random_uuid(), 9, 'g9', 'U1', '九年级 U1 完形:How Li Lei Changed', 'Li Lei used to be weak in English. He could not understand the teacher and was afraid to __1__ in class. Then he decided to change. Every morning he read English __2__ for twenty minutes to improve his pronunciation. He also built his __3__ by making word cards and reviewing them on the bus. When he met a new word, he tried to guess its meaning by __4__ the sentences around it. In class, he became more __5__ and often asked the teacher questions. He knew that everyone makes __6__, so he was __7__ with himself and never gave up. He also joined an English club, where he made many __8__. Little by little, his English __9__. Now he can have a conversation with foreign visitors easily. Li Lei says that anyone can learn English well by working hard and finding the right __10__.', 144, 3, '[{"q": "1", "answer": "B", "options": ["sleep", "speak", "sing", "run"], "explanation": "afraid to speak in class 害怕在课上发言。"}, {"q": "2", "answer": "A", "options": ["aloud", "quietly", "slowly", "alone"], "explanation": "read aloud 朗读以改善发音。"}, {"q": "3", "answer": "B", "options": ["grammar", "vocabulary", "pronunciation", "knowledge"], "explanation": "make word cards 是为扩大 vocabulary。"}, {"q": "4", "answer": "C", "options": ["writing", "copying", "reading", "drawing"], "explanation": "by reading the sentences around it 读上下文猜词义。"}, {"q": "5", "answer": "D", "options": ["quiet", "shy", "tired", "active"], "explanation": "常提问→更 active 积极。"}, {"q": "6", "answer": "A", "options": ["mistakes", "friends", "notes", "plans"], "explanation": "everyone makes mistakes 人人都会犯错。"}, {"q": "7", "answer": "B", "options": ["angry", "patient", "busy", "strict"], "explanation": "对自己有耐心 patient,不放弃。"}, {"q": "8", "answer": "C", "options": ["problems", "mistakes", "friends", "enemies"], "explanation": "加入俱乐部→结交许多 friends。"}, {"q": "9", "answer": "C", "options": ["fell", "stopped", "improved", "disappeared"], "explanation": "坚持努力→英语 improved 提高。"}, {"q": "10", "answer": "D", "options": ["time", "place", "reason", "way"], "explanation": "find the right way 找到正确方法,呼应全文。"}]'::jsonb, 1 WHERE NOT EXISTS (SELECT 1 FROM public.junior_cloze WHERE volume='g9' AND unit='U1' AND title='九年级 U1 完形:How Li Lei Changed');
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) SELECT gen_random_uuid(), 9, '九年级 U1 听力·对话 How Sarah Studies', '九上 Unit1 听力', 2, 'Lin Tao: Hi, Sarah! The English exam is coming. How do you study for it?
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) SELECT gen_random_uuid(), 9, '九年级 U1 听力·短文 How Mike Changed', '九上 Unit1 听力', 2, 'My name is Mike. Last year my English was poor, but now I am one of the best students in my class. How did I change? First, I learned grammar by doing exercises every day. Second, I increased my vocabulary by reading newspapers and writing down useful expressions. I also practised speaking by talking with my foreign teacher after class. At first it was hard, but I never gave up. Now I really enjoy learning English, and I believe everyone can become a good learner by working hard and finding the right way.', '我叫迈克。去年我的英语很差,但现在我是班上最好的学生之一。我怎么改变的?第一,我每天通过做练习学语法。第二,我通过读报纸、记下有用表达来扩大词汇量。我还通过课后和外教交谈练口语。起初很难,但我从不放弃。现在我很享受学英语,我相信只要努力并找到正确方法,人人都能成为优秀的学习者。', 'us_male', '[{"q": "How was Mike''s English last year?", "type": "choice", "answer": "A", "options": ["Poor.", "Excellent.", "Just OK.", "The best."]}, {"q": "How did Mike learn grammar?", "type": "choice", "answer": "D", "options": ["By listening to tapes.", "By watching TV.", "By chatting online.", "By doing exercises every day."]}, {"q": "How did Mike increase his vocabulary?", "type": "choice", "answer": "B", "options": ["By playing word games.", "By reading newspapers and writing down expressions.", "By memorizing the dictionary.", "By writing letters."]}, {"q": "How did Mike practise speaking?", "type": "choice", "answer": "C", "options": ["By reading aloud at home.", "By recording himself.", "By talking with his foreign teacher.", "By singing songs."]}, {"q": "What does Mike believe?", "type": "choice", "answer": "A", "options": ["Everyone can become a good learner by working hard.", "English is useless.", "Only clever students learn well.", "Learning English is impossible."]}]'::jsonb, '[]'::jsonb, 'short', 'g9', 'U1' WHERE NOT EXISTS (SELECT 1 FROM public.junior_listening_exercises WHERE volume='g9' AND unit='U1' AND title='九年级 U1 听力·短文 How Mike Changed');
INSERT INTO public.junior_writing_prompts (id, grade, topic, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, difficulty, title_en, high_sentences, error_pairs, paragraph_template, volume, unit) SELECT gen_random_uuid(), 9, 'How I Study English', '以 “How I Study English(我怎样学习英语)” 为题写一篇短文(80 词左右)。要点:至少写出 3 种你的学习方法；必须使用本单元句型 “… by doing …”；结尾给出一句鼓励或建议', 'Write a short passage on the topic: "How I Study English".', '["至少写出 3 种你的学习方法", "必须使用本单元句型 “… by doing …”", "结尾给出一句鼓励或建议"]'::jsonb, 70, 100, 'Everyone wants to learn English well, and here is how I do it. I build my vocabulary by making word cards and reviewing them every morning. I improve my listening by watching English cartoons, and I practise speaking by talking with my classmates in English. When I meet a new word, I find out its meaning by reading the sentences around it. Learning a language takes time, so be patient. If you keep working hard and find the right way, you will surely become a good learner!', '【15 分制】A 档(13-15):3+ 学习方法、正确使用 by+doing、语法基本无误、条理清楚;B 档(10-12):方法较全、少量错误;C 档(7-9):方法偏少、句型简单、错误较多;D 档(0-6):内容不完整、错误多。', 3, 'How I Study English', '["I build my vocabulary by making word cards.（我通过做单词卡片积累词汇。）", "I improve my listening by watching English videos.（我通过看英语视频提高听力。）", "I practise speaking by talking with my classmates.（我通过和同学交谈练习口语。）", "When I meet a new word, I guess its meaning by reading the sentences around it.（遇到生词时,我通过读上下文猜词义。）", "Learning a language takes time, so be patient.（学习语言需要时间,要有耐心。）"]'::jsonb, '[{"wrong": "I study English by read books.", "correct": "I study English by reading books.", "note": "介词 by 后接动名词 doing。"}, {"wrong": "I improve it by listen to tapes.", "correct": "I improve it by listening to tapes.", "note": "by + 动名词。"}, {"wrong": "How you study English?", "correct": "How do you study English?", "note": "一般现在时特殊疑问要加助动词 do。"}]'::jsonb, '【段落结构模板】
