-- ===== junior_listening_exercises (预期 2) =====
Sarah: I study by reading English stories every night. It helps me learn new words.
Lin Tao: That''s a good idea. But I always forget new words quickly.
Sarah: You can try making word cards and reviewing them on the bus.
Lin Tao: Sounds useful. What about listening? Mine is really weak.
Sarah: Don''t worry. I improved my listening by watching short English videos.
Lin Tao: How long do you watch them every day?
Sarah: About twenty minutes. Be patient, and you''ll get better step by step.
Lin Tao: Thank you, Sarah. I''ll start tonight!', '林涛:嗨,莎拉!英语考试快到了,你怎么备考?/莎拉:我每晚通过读英语故事来学习,这能帮我记新词。/林涛:好主意。可我总是很快忘掉新词。/莎拉:你可以试试做单词卡片,在公交车上复习。/林涛:听起来有用。听力呢?我很弱。/莎拉:别担心,我是通过看英语短视频提高听力的。/林涛:你每天看多久?/莎拉:大约二十分钟。要有耐心,你会一步步进步。/林涛:谢谢你,莎拉!我今晚就开始!', 'us_female', '[{"q": "How does Sarah study for the English exam?", "type": "choice", "answer": "C", "options": ["By playing games.", "By singing songs.", "By reading English stories.", "By drawing pictures."]}, {"q": "What does Sarah suggest for remembering words?", "type": "choice", "answer": "A", "options": ["Making word cards.", "Reading aloud.", "Copying the textbook.", "Asking the teacher."]}, {"q": "How did Sarah improve her listening?", "type": "choice", "answer": "D", "options": ["By taking notes.", "By reading novels.", "By making friends.", "By watching short English videos."]}, {"q": "How long does Sarah watch videos every day?", "type": "choice", "answer": "B", "options": ["About ten minutes.", "About twenty minutes.", "About half an hour.", "About one hour."]}, {"q": "What does Sarah tell Lin Tao to be?", "type": "choice", "answer": "C", "options": ["Careful.", "Quiet.", "Patient.", "Active."]}]'::jsonb, '[]'::jsonb, 'long', 'g9', 'U1' WHERE NOT EXISTS (SELECT 1 FROM public.junior_listening_exercises WHERE volume='g9' AND unit='U1' AND title='九年级 U1 听力·对话 How Sarah Studies');

-- ===== junior_writing_prompts (预期 1) =====
第1段:开场——Everyone wants to learn English well, and here is how I do it.
第2段:方法——I ... by doing ...（写出至少3种,用 by+doing 句型）
第3段:结尾——鼓励/建议:Learning takes time, so be patient. ... you will become a good learner!', 'g9', 'U1' WHERE NOT EXISTS (SELECT 1 FROM public.junior_writing_prompts WHERE volume='g9' AND unit='U1' AND topic='How I Study English');

COMMIT;

-- ===== count 校验(实际 vs 预期) =====
SELECT 'vocab' tbl, count(*) actual, 29 expected FROM public.junior_vocab WHERE volume='g9' AND unit='U1'
UNION ALL SELECT 'grammar_points', count(*), 3 FROM public.junior_grammar_points WHERE volume='g9' AND unit='U1'
UNION ALL SELECT 'grammar_questions', count(*), 60 FROM public.junior_grammar_questions x JOIN public.junior_grammar_points p ON x.point_id=p.id WHERE p.volume='g9' AND p.unit='U1'
UNION ALL SELECT 'reading', count(*), 6 FROM public.junior_reading WHERE volume='g9' AND unit='U1'
UNION ALL SELECT 'cloze', count(*), 1 FROM public.junior_cloze WHERE volume='g9' AND unit='U1'
UNION ALL SELECT 'listening', count(*), 2 FROM public.junior_listening_exercises WHERE volume='g9' AND unit='U1'
UNION ALL SELECT 'writing', count(*), 1 FROM public.junior_writing_prompts WHERE volume='g9' AND unit='U1';

-- ===== 校验3:未挂归属/未映射条目(应全部 0 行) =====
SELECT 'vocab_null_attr' chk, id::text, word detail FROM public.junior_vocab WHERE grade=9 AND (volume IS NULL OR unit IS NULL)
UNION ALL SELECT 'gpoint_null_attr', id::text, code FROM public.junior_grammar_points WHERE code LIKE 'g9u1.%' AND (volume IS NULL OR unit IS NULL OR category_id IS NULL)
UNION ALL SELECT 'gquestion_orphan', x.id::text, x.stem FROM public.junior_grammar_questions x LEFT JOIN public.junior_grammar_points p ON x.point_id=p.id WHERE x.grammar_topic LIKE 'g9u1.%' AND p.id IS NULL
UNION ALL SELECT 'reading_null_attr', id::text, title FROM public.junior_reading WHERE grade=9 AND (volume IS NULL OR unit IS NULL)
UNION ALL SELECT 'cloze_null_attr', id::text, title FROM public.junior_cloze WHERE grade=9 AND (volume IS NULL OR unit IS NULL)
UNION ALL SELECT 'listening_null_attr', id::text, title FROM public.junior_listening_exercises WHERE grade=9 AND (volume IS NULL OR unit IS NULL)
UNION ALL SELECT 'writing_null_attr', id::text, topic FROM public.junior_writing_prompts WHERE grade=9 AND (volume IS NULL OR unit IS NULL);